import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { describe, expect, it } from 'vitest';
import { judgeS6Replay, S6_REPLAY_DOMAIN, S6_REPLAY_LAYOUTS } from '../src/index.js';
import type { S6Settlement, S6Verdict } from '../src/index.js';

/**
 * The S6 replay-guard conformance suites (certen:s6-replay:v1), generated by certen-validator cmd/s6replayvectors and judged
 * there by pkg/ethproof TestS6Replay1Vectors / TestS6Replay2Vectors / TestS6Replay3Vectors. The files are byte-identical
 * copies: MANIFEST pins manifest.json, which pins every vector file and the mutation corpus. The TypeScript verdict must equal
 * Go's on every vector and every mutation of every set: result, state, reason, beforeVerified and every established line.
 *
 * s6replay1: CertenAccountV7_3 pinned (certen-validator 851c0c0). s6replay2: CertenAccountV7_2 pinned as well (fc66e83);
 * s6replay1's verdicts are unchanged by it (s6replay1/SUPERSEDED.md). s6replay3 (RB10-B7, 0d4c872): named states held to the
 * settlement's chain and contract, a refutation stated only with its verified Before, canonical header RLP only, escaped hex
 * refused, every settlement envelope. s6replay1's superseded vectors are judged, as Go's TestS6Replay1Vectors judges them,
 * only through the superseded list below (s6replay1/SUPERSEDED.md), which states both verdicts.
 */
const sha256 = (b: Uint8Array): string => createHash('sha256').update(b).digest('hex');

type Vector = { name: string; description: string; settlement: S6Settlement; evidence: string; expect: S6Verdict };
type Mutation = { name: string; base: string; evidence: string; expect: S6Verdict };

const SETS = [
  { set: 's6replay1', manifestSha256: '10a36ab9dda73f8b81032c5b28c64bedea19746c729578aa489ddd6d5c3ed8ae', vectors: 89, mutations: 781 },
  { set: 's6replay2', manifestSha256: 'd64a107c90486acb194dc1bcfc6806935af8c125ed9c165becf3ec489adcc2b5', vectors: 10, mutations: 622 },
  { set: 's6replay3', manifestSha256: '026d489c3902dac66a3babbf1068abf451a22f3493f1ec6c80064ccff2547114', vectors: 42, mutations: 534 },
] as const;

const V = (result: string, state: string, reason: string): S6Verdict => ({ result, state, reason, beforeVerified: false, established: [] }) as S6Verdict;

/** certen-validator pkg/ethproof s6replay1_test.go s6Replay1Superseded (0d4c872): the expectation each s6replay1 file records,
 * the verdict judged now, and the vectors of the superseding set that state what holds instead. The files are never edited. */
const SUPERSEDED: Record<string, Record<string, { recorded: S6Verdict; now: S6Verdict; by: string[]; set: string }>> = {
  s6replay1: {
    '029_generation_v7_2_unpinned': {
      recorded: V('refused', 's6_replay_unproven', 'account_generation'),
      now: V('refused', 's6_replay_unproven', 'account_generation'),
      by: ['005_v7_2_proof_of_a_v7_3_call', '001_v7_2_valid_execute'],
      set: 's6replay2',
    },
    '047_state_unproven_account_generation': {
      recorded: V('stated', 's6_replay_unproven', 'account_generation'),
      now: V('stated', 's6_replay_unproven', 'account_generation'),
      by: ['001_v7_2_valid_execute', '002_v7_2_valid_batch'],
      set: 's6replay2',
    },
    '049_state_refuted_slot_set_at_parent': {
      recorded: V('stated', 's6_replay_refuted', 'slot_set_at_parent'),
      now: V('refused', 's6_replay_unproven', 'parent_header_unproven'),
      by: ['006_refuted_with_verified_before', '007_refuted_without_before', '008_refuted_with_another_parent'],
      set: 's6replay3',
    },
  },
};

/** s6replay3_test.go TestS6Replay3Vectors: the statements the set exists for, pinned by name (result and reason). */
const S6REPLAY3_PINNED: Record<string, string> = {
  '002_state_of_another_chain': 'refused contract_mismatch',
  '003_state_of_another_contract': 'refused contract_mismatch',
  '004_state_receipt_unavailable_no_contract': 'stated receipt_unavailable',
  '005_state_unavailable_no_contract': 'refused contract_mismatch',
  '006_refuted_with_verified_before': 'stated slot_set_at_parent',
  '007_refuted_without_before': 'refused proof_does_not_verify',
  '008_refuted_with_another_parent': 'refused parent_header_unproven',
  '010_header_non_canonical_rlp': 'refused proof_does_not_verify',
  '013_envelope_legacy_pre_eip155': 'proven ',
  '014_envelope_legacy_eip155': 'proven ',
  '015_envelope_legacy_eip155_other_chain': 'refused contract_mismatch',
  '016_envelope_type1_access_list': 'proven ',
  '018_envelope_type3_blob_canonical': 'proven ',
  '019_envelope_type3_blob_sidecar_v0': 'proven ',
  '020_envelope_type3_blob_sidecar_v1': 'proven ',
  '021_envelope_type4_set_code': 'proven ',
  '023_escaped_hex_proof_contract': 'refused wrong_type',
  '035_escaped_hex_state_txhash': 'refused wrong_type',
  '039_escaped_hex_order_after_schema': 'refused unknown_field',
  '040_escaped_hex_order_before_version': 'refused wrong_type',
  '041_escaped_hex_order_before_one_of': 'refused wrong_type',
  '042_escaped_string_control': 'proven ',
};

for (const S of SETS) {
  const dir = new URL(`./fixtures/${S.set}/`, import.meta.url);
  const read = (name: string): Buffer => readFileSync(new URL(name, dir));
  const manifestRaw = read('manifest.json');
  const manifest = JSON.parse(manifestRaw.toString('utf8'));
  const superseded = SUPERSEDED[S.set] ?? {};

  describe(`S6 replay-guard conformance ${S.set} (certen:s6-replay:v1)`, () => {
    it('the files are the pinned copies', () => {
      expect(sha256(manifestRaw)).toBe(S.manifestSha256);
      expect(read('MANIFEST').toString('utf8')).toBe(`${S.manifestSha256}  manifest.json\n`);
      expect(manifest.domain).toBe(S6_REPLAY_DOMAIN);
      expect(manifest.vectors.length).toBe(S.vectors);
      for (const e of manifest.vectors) expect(sha256(read(e.file)), e.file).toBe(e.sha256);
      const gz = read(manifest.mutations.file);
      expect(sha256(gz)).toBe(manifest.mutations.sha256);
      expect(sha256(gunzipSync(gz))).toBe(manifest.mutationsJsonSha256);
    });

    const vectors: Vector[] = manifest.vectors.map((e: { file: string }) => JSON.parse(read(e.file).toString('utf8')));
    const byName = new Map(vectors.map((v) => [v.name, v]));

    it(`judges all ${S.vectors} vectors exactly as Go does`, () => {
      const diffs: string[] = [];
      for (const v of vectors) {
        const got = judgeS6Replay(v.settlement, new TextEncoder().encode(v.evidence));
        const sup = superseded[v.name];
        if (sup !== undefined && JSON.stringify(v.expect) !== JSON.stringify(sup.recorded)) {
          diffs.push(`${v.name}: the file records ${JSON.stringify(v.expect)}, the superseded list ${JSON.stringify(sup.recorded)}`);
        }
        const want = sup === undefined ? v.expect : sup.now;
        if (JSON.stringify(got) !== JSON.stringify(want)) diffs.push(`${v.name}: TS ${JSON.stringify(got)} Go ${JSON.stringify(want)}`);
      }
      expect(diffs).toEqual([]);
    });

    it('every superseded vector is in the set and superseded by committed vectors', () => {
      for (const [name, sup] of Object.entries(superseded)) {
        expect(byName.has(name), name).toBe(true);
        for (const by of sup.by) {
          expect(existsSync(new URL(`./fixtures/${sup.set}/${by}.json`, import.meta.url)), `${name} by ${sup.set} ${by}`).toBe(true);
        }
      }
    });

    it(`judges all ${S.mutations} mutations exactly as Go does`, () => {
      const muts: Mutation[] = JSON.parse(gunzipSync(read(manifest.mutations.file)).toString('utf8'));
      expect(muts.length).toBe(manifest.mutationCount);
      expect(muts.length).toBe(S.mutations);
      const diffs: string[] = [];
      for (const m of muts) {
        const base = byName.get(m.base);
        expect(base, m.name).toBeDefined();
        expect(m.evidence).not.toBe(base!.evidence);
        const got = judgeS6Replay(base!.settlement, new TextEncoder().encode(m.evidence));
        if (JSON.stringify(got) !== JSON.stringify(m.expect)) diffs.push(`${m.name}: TS ${JSON.stringify(got)} Go ${JSON.stringify(m.expect)}`);
        if (S.set === 's6replay3') {
          if (m.name.includes('/escape_') && (m.expect.result !== 'refused' || m.expect.reason !== 'wrong_type')) {
            diffs.push(`${m.name}: an escaped hex value is not refused wrong_type`);
          }
          if (m.expect.result === 'proven' && !m.name.includes('beforeUnavailable.providers')) {
            diffs.push(`${m.name} is proven: a mutation of what the verifier checks must not verify`);
          }
        }
      }
      expect(diffs).toEqual([]);
    });

    it('every established line names the proof generation, a row of the pinned table', () => {
      for (const v of vectors.filter((x) => x.expect.result === 'proven')) {
        const gen = JSON.parse(v.evidence).proof.generation;
        expect(Object.keys(S6_REPLAY_LAYOUTS)).toContain(gen);
        const got = judgeS6Replay(v.settlement, new TextEncoder().encode(v.evidence));
        expect(got.established[0]).toContain(`(${gen} _consumedLeaf[leaf]`);
      }
    });

    if (S.set === 's6replay3') {
      it('the statements s6replay3 exists for, pinned by name', () => {
        for (const [name, w] of Object.entries(S6REPLAY3_PINNED)) {
          const v = byName.get(name);
          expect(v, name).toBeDefined();
          expect(`${v!.expect.result} ${v!.expect.reason}`, name).toBe(w);
        }
        expect(byName.get('006_refuted_with_verified_before')!.expect.beforeVerified).toBe(true);
      });
    }
  });
}
